const FAMILY_SKILL_TYPE: Record<string, SkillType> = {
  "passe-recepcao": "pass",
  saque: "serve",
  levantamento: "set",
  ataque: "attack",
  bloqueio: "block",
  defesa: "defense",
  libero: "libero",
  rodizio: "rotation",
  cobertura: "coverage",
  transicao: "transition",
  comunicacao: "communication",
  "jogo-reduzido": "smallSided",
  condicionamento: "conditioning",
  pressao: "pressure",
};

function buildFamilyLocale(family: Family, levelIndex: 0 | 1 | 2, locale: Locale): CuratedTemplate {
  const lvl = family.levels[levelIndex];
  return {
    slug: `${family.id}-${levelIndex}`,
    skillType: FAMILY_SKILL_TYPE[family.id] ?? "pass",
    category: LEVEL_LABEL[levelIndex][locale],
    hook: lvl.hook[locale],
    title: lvl.title[locale],
    subtitle: lvl.subtitle[locale],
    objective: lvl.objective[locale],
    courtSetup: COURT_SETUP[family.courtSetup][locale],
    totalDurationMin: LEVEL_DURATION[levelIndex],
    playersCount: LEVEL_PLAYERS[levelIndex],
    intensity: LEVEL_INTENSITY[levelIndex],
    materials: family.materials.map((m) => MATERIAL[m][locale]),
    coverFrom: family.coverFrom,
    coverTo: family.coverTo,
    blocks: family.blocksByLevel[levelIndex].map((b) => ({
      order: b.order,
      durationMin: b.durationMin,
      title: b.title[locale],
      description: b.description[locale],
      coachingPoints: b.coachingPoints[locale],
      technicalActions: b.technicalActions[locale],
      tacticalPrinciple: b.tacticalPrinciple[locale],
      variants: b.variants[locale],
      diagram: b.diagram,
    })),
  };
}

export function buildFamilyTemplates(locale: Locale): CuratedTemplate[] {
  const out: CuratedTemplate[] = [];
  for (const family of FAMILIES) {
    for (const idx of [0, 1, 2] as const) {
      out.push(buildFamilyLocale(family, idx, locale));
    }
  }
  return out;
}
